window.__saqPaperQuestions("2025-1-pah",[{"number":1,"title":"","stemText":"A 28 year old woman has presented with 2 days of left facial swelling and pain.\nA clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 differential diagnoses. Provide a key feature of your history or examination that\nwould support each diagnosis. (8 marks) Diagnosis Key feature (Hx or Ex)"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you might perform. Provide justification for each. (4 marks)"}],"propPages":["asset:imgf8851948163a0b648e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Bacterial parotitis – fevers, septic/abnormal vital signs</div><div class=\"answer-line\">Viral parotitis – not immunised mumps</div><div class=\"answer-line\">Sialolithiasis – palpable stone Stensen’s duct (parotid duct)</div><div class=\"answer-line\">Dental abscess – poor dentition, abscess gingiva</div><div class=\"answer-line\">Malignancy eg lymphoma – non-tender, B-symptoms</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>USS – looking for abscess in bacterial parotitis or stone in sialoadenitis</td><td>Viral swab mouth – mumps</td></tr><tr><td>Serology mumps</td><td>OPG – when dental infection suspected – for abscess</td></tr><tr><td>CT face/neck – looking for abscess / deep space infection where trismus present or tracking infection</td><td>suspected</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 70 year old man has presented via ambulance with acute shortness of breath.\nHis vital signs are:\n\nGCS\n\nHR\n110 /min\n\nBP\n200/110 mmHg O2 sats 89% 15L O2 via non-rebreather mask\n\nRR\n/min\n\nTemp\n36.5 degrees His chest x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State your provisional diagnosis, supported by 4 findings on the chest x-ray. (5 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 treatment measures you would initiate. For each, provide the physiological\nmechanism of its effect. (6 marks) Treatment measure Mechanism"}],"propPages":["asset:img9864ae78e952472357"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Bilateral alveolar airspace opacity</td></tr><tr><td>-</td><td>Cardiomegaly</td></tr><tr><td>-</td><td>Kerley B lines</td></tr><tr><td>-</td><td>Bilateral pleural effusions</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>CPAP/NIV</strong> – reduce preload to decrease BP, improve oxygenation by splinting open small airways,</td><td>decrease myocardial wall tension</td></tr><tr><td><strong>GTN</strong> – reduce preload, decrease BP</td><td>Frusemide 40mg IV – reduce preload</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 65 year old woman has presented with shortness of breath 2 weeks after a CABG and mechanical aortic valve replacement.","parts":[{"id":"p1","label":"Part 1","prompt":"Complete the following table with 6 differential diagnoses and a discriminatory examination finding for each. (6 marks) Differential diagnosis Examination finding During your assessment she becomes hypotensive with a blood pressure of 70/40. You elect to perform a bedside echocardiogram."},{"id":"p2","label":"Part 2","prompt":"List 6 findings on echocardiogram that may be present, including the relevance of each.\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>PE</strong> – RV heave, loud P2, raised JVP, evidence DVT</td><td>Pericardial effusion – rub, muffled HS, raised JVP, pulsus paradoxus</td></tr><tr><td>Pneumonia – fever, focal findings eg crackles</td><td>Aortic valve regurgitation – diastolic murmur of AR, pulmonary oedema, peripheral oedema</td></tr><tr><td>Pleural effusion – decreased BS / dull percussion note</td><td>Myocardial infarction / graft occlusion – pale, sweaty, in pain, new CCF (hard to be specific for this</td></tr><tr><td>one)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Collapsed IVC / hyperdynamic LV – hypovolaemia, haemorrhage</div><div class=\"answer-line\">New AR / AV valve vegetation – endocarditis / valve infection</div><div class=\"answer-line\">New RWMA – MI</div><div class=\"answer-line\">Dilated RV – PE</div><div class=\"answer-line\">Intrapleural fluid c/w effusion/empyema</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 60 year old man has presented with palpitations and an episode of syncope.\nHe looks pale and sweaty.\nHis vital signs are:\n\nGCS\n\nBP\n90/60 mmHg\n\nRR\n/min O2 sats 97% room air His ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide your diagnosis, supported by 4 findings on the ECG. (5 marks)"},{"id":"p2","label":"Part 2","prompt":"List 5 potential causes of this problem. (5 marks)\nYou have elected to electrically cardiovert the patient."},{"id":"p3","label":"Part 3","prompt":"State 5 components of this procedure. (5 marks)\nThe electrical cardioversion was unsuccessful."},{"id":"p4","label":"Part 4","prompt":"List 2 drugs you might use to manage this problem, including initial doses. List one\npotential adverse effect for each drug. (4 marks) Drug Adverse Effect"}],"propPages":["asset:img3fd40432ad0ba205e8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">RVOT <strong>VT</strong></td></tr><tr><td>-</td><td>Broad complex</td></tr><tr><td>-</td><td>Tachycardia approx 160</td></tr><tr><td>-</td><td>Regular</td></tr><tr><td>-</td><td>AV dissociation present</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">MI</div><div class=\"answer-line\">Hypokalaemia</div><div class=\"answer-line\">Drugs eg TCA</div><div class=\"answer-line\">Primary eg RVOT VT</div><div class=\"answer-line\">Channelopathy eg Brugada</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Consent / explanation</div><div class=\"answer-line\">Pads anterolat or AP</div><div class=\"answer-line\"><strong>Sync </strong></div><div class=\"answer-line\">Energy 200J</div><div class=\"answer-line\">Sedation eg careful midazolam 1-2mg aliquots</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Amiodarone 5mg/kg – hyperthyroidism</td><td>Lignocaine 1mg/kg – CNS toxicity eg seizures</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 2 year old girl has presented with abdominal pain, distension and vomiting. She has been febrile and lethargic at home. Her abdominal x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide your interpretation of the x-ray, including 3 supportive radiographic abnormalities. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 investigations you will perform, with justification. (3 marks)\nInvestigation Justification The patient’s vital signs are: Responds to pain\n\nHR\n160 /min\n\nBP\n60/40 /mmHg\n\nRR\n/min O2 sats 99% room air\nTemperature 39.5\ndegrees"},{"id":"p3","label":"Part 3","prompt":"State 5 components of your management. (5 marks)"}],"propPages":["asset:img37683ae4ebd3469ab5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Small bowel obstruction</strong> due to intussusception</td></tr><tr><td>-</td><td>Dilated small bowel</td></tr><tr><td colspan=\"2\">o Plicae circulares</td></tr><tr><td>-</td><td>No distal gas</td></tr><tr><td>-</td><td>No gas RUQ</td></tr><tr><td>-</td><td>Crescent sign right side</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>USS </strong>– confirm intussusception for intervention</div><div class=\"answer-line\">Venous blood gas – define degree of hypoperfusion – lactate / HAGMA</div><div class=\"answer-line\">BSL – exclude hypoglycaemia requiring correction</div><div class=\"answer-line\">Chem 20 – define Na/K loss due to third spacing</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>IV N/S 20mL/kg</strong> stat repeat if required aiming for BP &gt; 85</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Norad infusion if not achieving BP</div><div class=\"answer-line\"><strong>IV Abs</strong> – pip/taz 100mg/kg or amp/gent/flagyl</div><div class=\"answer-line\">Analgesia – fentanyl 1mcg/kg</div><div class=\"answer-line\"><strong>Urgent surgical consult</strong> – suspected perforation with intuss for OT</div><div class=\"answer-line\">NGT / IDC</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A new study has shown the use of a D-dimer is able to rule out aortic dissection in a specific patient cohort.","parts":[{"id":"p1","label":"Part 1","prompt":"How is Bayes’ Theorem utilised in clinical diagnostic testing? (1 mark) The study showed that use of a D-dimer in this cohort had a negative predictive value of 99.7% (95%\nconfidence interval 99.1-100%)."},{"id":"p2","label":"Part 2","prompt":"What does this confidence interval mean? (1 mark)"},{"id":"p3","label":"Part 3","prompt":"What is a negative predictive value? (1 mark)"},{"id":"p4","label":"Part 4","prompt":"What values are required to calculate a negative predictive value? (3 marks)"},{"id":"p5","label":"Part 5","prompt":"What is the difference between a negative predictive value and the sensitivity of a test? (1 mark) You elect to introduce this diagnostic strategy in your practice and disseminate this to your consultant colleagues."},{"id":"p6","label":"Part 6","prompt":"What are 3 potential negative outcomes of this from a systems perspective? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">The pre-test probability combined with the likelihood ratio of a specific diagnostic test are used to</div><div class=\"answer-line\">determine the post-test probability of a disease</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">The true negative predictive value is 95% likely to lie within 99.1 and 100%</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">The likelihood that a patient testing negative for a disease actually does not have that disease</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Sensitivity</div><div class=\"answer-line\">Specificity</div><div class=\"answer-line\">pre-test probability</div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">NPV depends upon pre-test probability while sensitivity does not</div></section><section class=\"answer-part\"><h5>Part 6</h5><div class=\"answer-line\">Increased D-dimer testing of patients who may not have had any investigations in the past</div><div class=\"answer-line\">Potential for a missed diagnosis of aortic dissection (given NPV not 100%)</div><div class=\"answer-line\">Potential for increased D-dimer testing and if positive, subsequent aortography that may not have</div><div class=\"answer-line\">been performed otherwise</div><div class=\"answer-line\">Delay to rule in or out if CT aortogram delayed awaiting D-dimer results with risk of deterioration in</div><div class=\"answer-line\">interim, slowed flow through department and contribution to overcrowding</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 65 year old woman has presented after a witnessed fall at home. She has an isolated head injury. She takes dabigatran for atrial fibrillation. A slice form her non-contrast CT head is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 abnormalities on the CT image provided. (6 marks)\nShortly after arrival, the patient has a decreased level of consciousness.\nHer vital signs are:\nGSC E1 V1 M2\n\nHR\n/min\n\nBP\n190/110 mmHg\n\nRR\n/min O2 sats 98% room air Her left pupil is fixed and dilated."},{"id":"p2","label":"Part 2","prompt":"State 6 components of your management. (6 marks)"}],"propPages":["asset:imgef83f28cdac4659be9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Swirl sign indicative of rapid bleeding</div><div class=\"answer-line\">Midline shift to right</div><div class=\"answer-line\">Subfalcine herniation</div><div class=\"answer-line\">Effaced left lateral ventricle</div><div class=\"answer-line\">Dilated right lateral ventricle concerning for obstructive hydrocephalus</div><div class=\"answer-line\">Right occipital extracranial haematoma</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Intubation RSI</strong> – drugs and doses</div><div class=\"answer-line\">Hyperventilate aim pCO2 30mmHg</div><div class=\"answer-line\">Hypertonic saline 5ml/Kg 3% or mannitol 1g/kg</div><div class=\"answer-line\"><strong>Urgent neurosurgical consultation </strong></div><div class=\"answer-line\">Neuroprotective measures specify – 1 mark only</div><div class=\"answer-line\">Reverse dabigatran – Idarucizumab 2.5g x 2 IV stat</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 5 year old boy has been brought to your ED by his mother after an apparent snake bite while playing in the yard. He has an appropriate pressure immobilisation bandage in place from the ambulance service. He is currently asymptomatic.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 features on your history and/or examination that would suggest a brown snake\nenvenomation. (4 marks) His coagulation studies are:\n\nINR\n>10 (<1.5) Fibrinogen unrecordable"},{"id":"p2","label":"Part 2","prompt":"What is the diagnosis? (1 mark) After discussion with the on-call Toxicologist, you decide to give the patient a single vial of brown snake antivenom. During the infusion, the patient develops a reduced level of consciousness."},{"id":"p3","label":"Part 3","prompt":"List 3 differential diagnoses and a feature on examination that would support each.\n(3 marks) Differential diagnosis Examination feature The patient responds to your treatment and has completed their treatment course. You are planning on discharging the patient the next day."},{"id":"p4","label":"Part 4","prompt":"What potential complications of this presentation might the patient experience while at home and what signs is the mother to look for that would require medical review? (4 marks) Potential complication Signs"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["dimer 12.0 mg/L (<0.5mg/L)"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Bleeding from gums/IVC/bite site – Concern for VICC</div><div class=\"answer-line\">Initial collapse</div><div class=\"answer-line\">Witnessed brown snake (although often unreliable)</div><div class=\"answer-line\">Geographic area likely brown snake</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Complete VICC</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Intracranial haemorrhage –</strong> Localising neurology, blown pupil</div><div class=\"answer-line\">Intra-abdominal or other source of haemorrhagic shock – Peritonitic, shock state</div><div class=\"answer-line\">Anaphylaxis to antivenom – Widespread rash, urticaria, stridor, bronchospasm</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Risk of thrombotic microangiopathy – Monitor for reduced urine output</div><div class=\"answer-line\">Risk of serum sickness – Monitor for flu-like illness / rash</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 28 year old man has been brought in to your tertiary ED at midnight after being thrown out of a car in the ambulance offload area. He has sustained a single gunshot wound to the epigastrium. His initial vital signs are:\n\nGCS\nE2 V4 M5\n\nHR\n160 /min\n\nBP\n60/40 mmHg\n\nRR\n/min\n\nSpO2\n86% 15 L/min via non-rebreather mask His chest x-ray shows a right haemopneumothorax with radiological tension.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 components of your initial management. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 5 additional investigative findings you would seek and state how each would influence your management. (5 marks) Shortly after your initial management, the patient has a cardiac arrest (pulseless electrical activity). You intend to perform a resuscitative thoracotomy."},{"id":"p3","label":"Part 3","prompt":"List 4 potentially life-saving interventions you might perform as part of a resuscitative\nthoracotomy. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"State 6 steps in the performance of a resuscitative thoracotomy where access to the heart\nis gained. (6 marks)\nPAH 2025.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Simultaneous – intubate – ketamine up to 50mg, roc/sux doses</div><div class=\"answer-line\"><strong>Thoracostomy right side followed by ICC </strong></div><div class=\"answer-line\">Activate trauma call – surgical team attendance</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Pericardial blood on FAST – needing thoracotomy</div><div class=\"answer-line\"><strong>IP blood on FAST</strong> – need for laparotomy</div><div class=\"answer-line\">VBG – degree of lactic acidosis – aid in transfusion requirements</div><div class=\"answer-line\">ROTEM Fibtem A5 – define need for fibrinogen (cryo or fib-conc)</div><div class=\"answer-line\">Ionised Ca – requirement for Ca supplementation as part of MTP</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Pericardotomy for tamponade</div><div class=\"answer-line\">Suture/staple cardiac laceration</div><div class=\"answer-line\">Balloon tamponade cardiac laceration</div><div class=\"answer-line\">Compress aorta</div><div class=\"answer-line\">Perform open CPR</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">PPE</div><div class=\"answer-line\">Left sided incision 5th interspace – lateral sternum to axilla</div><div class=\"answer-line\">(Puncture pleura mid axillary line as for thoracostomy)</div><div class=\"answer-line\">Scissors to intercostal muscles</div><div class=\"answer-line\">Rib-spreaders inserted to expose left hemi-thorax</div><div class=\"answer-line\">Incise pericardial sac avoiding phrenic nerve</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 58 year old man has presented to the ED with gradual onset of a swollen, painful right testicle.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 features of your history. Include the relevance of each feature. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you might perform. Provide justification for each. (4 marks)\nYour provisional diagnosis is epididymo-orchitis. You are planning to manage him as an outpatient."},{"id":"p3","label":"Part 3","prompt":"State 4 components of your management. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Urinary symptoms – suggestive UTI</div><div class=\"answer-line\">Hx STIs / unprotected sex – risk chlamydia/gonorrhea</div><div class=\"answer-line\">Treatment to date - ?failed outpt Rx already</div><div class=\"answer-line\">Risks for severe illness – DM, immunocompromise – need admission</div><div class=\"answer-line\">How sick – vomiting, fevers, syncope – may mandate admission</div><div class=\"answer-line\">Allergies – define drugs used</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>Urine M/C/S</strong> – conform/exclude UTI – also guide antibiotic choice once sensitivities back</td><td>First pass urine chlamydia/gono PCR – diagnose STI – different Ab Rx, contact tracing</td></tr><tr><td>USS – perform if abscess suspected on examination – might need surgery</td><td>Chem 20 – define renal function especially if unwell and risk AKI – modify aminoglycoside dosing</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Analgesia – paracetamol / NSAIDS with doses</div><div class=\"answer-line\"><strong>Abs </strong>– will be cause dependent – UTI eg 2 weeks cephalexin 500mg tds, STI ceftriaxone 1g then</div><div class=\"answer-line\">azithro 1g po now and 1 week</div><div class=\"answer-line\">Needs follow up of urine / STI results to ensure appropriate Abs, contact tracing</div><div class=\"answer-line\">Advice on when to return – unwell from sepsis (fevers, vomiting, light-headed), getting worse</div><div class=\"answer-line\">despite Rx</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 65 year old man has been brought to the ED by ambulance. He has been feeling dizzy and unwell\nfor 24 hours.\nHis medical history includes: Hypertension Chronic Kidney Disease Permanent pacemaker for previous complete heart block Hypercholesterolaemia His ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the ECG. (5 marks) The patient’s vital signs are:\n\nGCS\nE4 V4 M6\n\nBP\n100/60 mmHg\n\nRR\n/min O2 sats 98% room air"},{"id":"p2","label":"Part 2","prompt":"State 4 components of your management. Explain the mechanism of action of each.\n(4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 potential precipitants of this problem. (3 marks)"}],"propPages":["asset:img948584f116e88a975f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Ventricular pacing</td></tr><tr><td colspan=\"2\">Signs of hyperkalaemia</td></tr><tr><td>-</td><td>Pacing latency (slow to pace after spike)</td></tr><tr><td>-</td><td>Broad QRS</td></tr><tr><td>-</td><td>Peaked T waves</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">IV HCO3 – 50mmol – serum alkalinisation – push K in to cells</div><div class=\"answer-line\">IV actrapid insulin 10U + dextrose 50mL 50% - push K in to cells</div><div class=\"answer-line\">Resonium oral – 15g – absorbs K in gut</div><div class=\"answer-line\">Also accept dialysis in CKD – direct removal K from blood</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Acute on chronic renal failure – K accumulation</div><div class=\"answer-line\">Medications eg ACE-I – increase K retention kidney</div><div class=\"answer-line\">Acidosis any cause – acute illness – shift out of cells</div><div class=\"answer-line\">Cell death eg rhabdomyolysis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 3 month old girl has been brought to the ED with difficulty breathing.\nYour provisional diagnosis is bronchiolitis.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 differential diagnoses. For each, state a finding on history or examination that\nwould suggest its presence. (3 marks) You are confident that the child has bronchiolitis."},{"id":"p2","label":"Part 2","prompt":"List 3 risk factors for development of severe bronchiolitis. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 treatment measures you might undertake. For each, provide the clinical\nindication. (4 marks) After a period of observation, you have decided that the child is suitable for discharge home."},{"id":"p4","label":"Part 4","prompt":"State 2 key pieces of information you would give the parents. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CCF – hepatomegaly, heart murmurs</td><td>Bacterial pneumonia – focal crackles / septic appearance eg hypotensive</td></tr><tr><td>Anaphylaxis to foods/milk – urticarial rash</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Chronic lung disease</div><div class=\"answer-line\">Congenital heart disease</div><div class=\"answer-line\">Chronic neurological conditions</div><div class=\"answer-line\">Gestational age &lt;37 weeks, or chronological age at presentation &lt;10 weeks</div><div class=\"answer-line\">Growth restriction</div><div class=\"answer-line\">Indigenous ethnicity</div><div class=\"answer-line\">Immunodeficiency</div><div class=\"answer-line\">Exposure to cigarette smoke</div><div class=\"answer-line\">Trisomy 21</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>O2 via NP – increased WOB with hypoxia sats &lt;90%</td><td>NG feeds – oral intake &lt;50%, clinically dehydrated</td></tr><tr><td>HFNP O2 – ongoing hypoxia despite low flow NP or more severe hypoxia and incr WOB</td><td>CPAP – severe disease</td></tr><tr><td>IV fluid eg N/S plus 5%D – where NG rehydration not possible</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Time course for illness – eg worse day 3-5 the gradual recovery over weeks</div><div class=\"answer-line\">When to return – can’t feed, pale/sweaty, blue, increased difficulty breathing</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 25 year old man has presented after a motor-bike accident.\nHe has an isolated right leg injury. His x-rays are provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the abnormalities. (4 marks) You are planning to perform procedural sedation as part of your management of the injury."},{"id":"p2","label":"Part 2","prompt":"State 4 features of your examination relevant to the performance of your procedural\nsedation. Provide the significance of each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 potential problems that might occur during the procedural sedation. State your\nmanagement of each. (4 marks)"}],"propPages":["asset:imgc264bfd080f90b8bb5","asset:imgaea471cc591c636983"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Subtalar dislocation</div><div class=\"answer-line\">– lateral displacement</div><div class=\"answer-line\">Fracture distal fibula</div><div class=\"answer-line\">Talus is also:</div><div class=\"answer-line\">Subluxed</div><div class=\"answer-line\">medially angulated</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Mallampatti grade – will estimate degree of difficulty of laryngoscopy if required for rescue</div><div class=\"answer-line\">Neck mobility – assess for potential issues with laryngoscopy if required for rescue</div><div class=\"answer-line\">Heart examination – severe AS makes anaesthesia with vasodilators risky</div><div class=\"answer-line\">Lungs- concurrent lung disease will decrease respiratory reserve before hypoxia experienced</div><div class=\"answer-line\">Lots of others</div><div class=\"answer-line\"><strong>Some sort of airway assessment essential </strong></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Hypotension – IV N/S bolus 1L aim BP &gt;100mmHg</div><div class=\"answer-line\">Vomit / aspiration – suction, airway support eg BVM / intubate if severe</div><div class=\"answer-line\">Prolonged Apnoea – support with BVM / adjuncts if hypoxia experienced</div><div class=\"answer-line\">Awareness – deepen sedation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A duress alarm has been triggered in your Emergency Department’s ambulance ramping area. An agitated patient who was brought to hospital on an emergency examination order, has attempted to leave. The patient has assaulted a member of the nursing staff who attempted to stop the patient from leaving. You have arrived to find the patient being restrained by 5 security guards on the floor\n• f a corridor.","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 factors you will consider in your management of this situation. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"List 6 potential factors that could have contributed to this event. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Assess safety of patient – eg is restraint allowing pt to breathe properly</div><div class=\"answer-line\">Assess safety of staff – are enough people present to manage both physical restraint and</div><div class=\"answer-line\">requirement for nursing/medical procedures</div><div class=\"answer-line\">Assess requirement for pt to stay – Hx collateral / pt – should pt continue to be detained for safety</div><div class=\"answer-line\">of self/others under Guardianship or MH act or is most appropriate measure t allow pt to go</div><div class=\"answer-line\">Arrange for assessment and management of injured nursing staff member in private room – will not</div><div class=\"answer-line\">return to work</div><div class=\"answer-line\">Counselling of nurse</div><div class=\"answer-line\">Move patient to trolley or more suitable area away from general public for</div><div class=\"answer-line\">assessment/management</div><div class=\"answer-line\">Facilitate sedation if required eg droperidol 10mg IM</div><div class=\"answer-line\">Notify critical incident</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">System factors</div><div class=\"answer-line\">Overcrowding resulting in patient in inappropriate area</div><div class=\"answer-line\">Lack of appropriate treatment protocols for aggressive patients</div><div class=\"answer-line\">Inadequate staff training to recognise / manage aggressive patient</div><div class=\"answer-line\">Not enough security staff to handle hospital requirements</div><div class=\"answer-line\">Patient factors</div><div class=\"answer-line\">Intoxicated / hungry / in pain</div><div class=\"answer-line\">Unrecognised illness / delirium</div><div class=\"answer-line\">There will be others</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 16 month old boy has been brought to your rural ED with fever, lethargy and refusal to swallow food or fluids. A lateral neck x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the pathology shown, with supportive radiographic evidence. (2 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 features of your history. Provide the clinical relevance for each. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 features of your examination. Provide the clinical relevance for each. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"List 3 investigations you would perform. Provide the clinical relevance for each. (3 marks) The patient requires emergent intubation to maintain airway patency. The patient’s vital signs are: AVPU alert Pulse 180 /min\n\nBP\n85/45 mmHg\n\nRR\n/min O2 sats 98% 15L O2 via non-rebreather mask"},{"id":"p5","label":"Part 5","prompt":"State 4 components of your airway management plan. (4 marks)"},{"id":"p6","label":"Part 6","prompt":"State 2 other components of your management. (2 marks)"}],"propPages":["asset:img3c69f94f2364a0f77d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>Epiglottitis</strong> – thumb print sign</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Vaccinations</strong> ?haemophilus as a cause – may alter Abs</td><td>PMHx- particularly cardiorespiratory problems that will effect reserve / ability to compensate for</td></tr><tr><td>sepsis</td><td>Assessment of dehydration - Time course / vomiting / oral intake / urine output</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>HR/BP/cap refill</strong>  – determine shock need for fluid resuscitation</td><td><strong>Assess for airway obstruction</strong> – stridor – need for emergent airway management</td></tr><tr><td>O2 sats / cyanosis - ?requires O2</td><td>Airway assessment as possible – any other features that would make intubation more challenging eg</td></tr><tr><td>small mandible / syndromes</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>VBG – determine degree of hypoperfusion with sepsis – lactate – assist guiding fluid resus</td><td>BSL – exclude hypoglycaemia in sepsis requiring Rx</td></tr><tr><td>BC – aim to identify pathogen to guide AB therapy in coming days</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">Pre-oxygenate with NRB sitting up, parents if possible</div><div class=\"answer-line\">Induce ketamine 1mg/kg roc 1.2mg/kg</div><div class=\"answer-line\">Bag through apnoea</div><div class=\"answer-line\">Use VL / smaller tube ready – 4 / 3.5 ETT</div><div class=\"answer-line\">Have needle cric kit ready</div></section><section class=\"answer-part\"><h5>Part 6</h5><div class=\"answer-line\">IV N/S 20ml/kg stats repeat if necessary – aim reduction HR / cap refill 2s</div><div class=\"answer-line\">IV Abs – cefotaxime 50mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 24 year old woman has been brought to your ED after falling down a set of stairs.\nShe is complaining of abdominal pain. She is 29 weeks pregnant. Your assessment reveals abdominal tenderness but no other injuries.\nHer vital signs are normal.","parts":[{"id":"p1","label":"Part 1","prompt":"List 7 investigations you might perform. Provide the clinical utility of each. (7 marks)\nFollowing your assessment, no injuries have been identified. During a period of observation, the patient begins to have regular painful contractions."},{"id":"p2","label":"Part 2","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"p3","label":"Part 3","prompt":"State 3 components of your management. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">FAST scan – looking for free fluid which would require further Ix / possibly operation</div><div class=\"answer-line\"><strong>CTG </strong>– looking for contractions / fetal decels c/w placental abruption / prem labour</div><div class=\"answer-line\">Uterine USS – looking for placental abruption / fetal wellbeing</div><div class=\"answer-line\">CT scan – if significant injury concerns eg positive FAST</div><div class=\"answer-line\"><strong>G+H</strong> – determine blood group if transfusion required, O neg will require anti-D</div><div class=\"answer-line\">Kleihauer test – looking for feto-maternal mixing in placental abruption</div><div class=\"answer-line\">x-ray pelvis – if concerns for pelvic fracture from examination</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Placental abruption causing premature labour</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Betamethasone 11.4mg IM</div><div class=\"answer-line\">analgesia</div><div class=\"answer-line\"><strong>Obstetric consult/transfer </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 78 year old man has been brought to the ED after being found lying on the floor of his kitchen. His medical history includes:\nType 2 diabetes mellitus, Hypertension, Atrial fibrillation\nHis medications are: Ramipril, Metoprolol, Metformin, Apixaban His arterial blood gas is provided below:\n\nFiO2\n0.50\n\npH\n7.29 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\n102 mmHg\n\nHCO3\nmmol/L (22 - 32) Base excess -14.7 mmol/L (-3.0 - 3.0)\n\nNa\n132 mmol/L (135 - 145)\n\nK\n4.8 mmol/L (3.5 - 5.2)\n\nCl\n100 mmol/L (95 - 110)\n\nGlucose\n18.4 mmol/L (3.0 - 7.8)\n\nLactate\n20.1 mmol/L (0.5 - 2.2)\n\nHb\ng/L (135 - 180)","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 abnormalities from the blood gas. Provide a likely clinical explanation for each.\n(6 marks) Abnormality Clinical explanation"},{"id":"p2","label":"Part 2","prompt":"List 6 components of your examination, including justification. (6 marks)"},{"id":"p3","label":"Part 3","prompt":"List 6 further investigations you might perform. Provide justification for each. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>HAGMA –</strong> lactic acidosis – hypoperfusion / MALA</td><td>Respiratory compensation for metabolic acidosis – appropriate</td></tr><tr><td>Raised A-a gradient – likely aspiration lung injury, possible pneumonia or PE</td><td>Low Na – corrects to normal for glucose – 136</td></tr><tr><td>Anaemia – potential bleeding given clinical stem, on anti-coagulation</td><td>High lactate – MALA</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Vital signs</strong> – looking for shock eg sepsis as cause for fall</div><div class=\"answer-line\"><strong>Signs head injury (</strong>anti-coaguated) – bruising/pupils/GCS – may need neurosurgery</div><div class=\"answer-line\">Lung examination / O2 sats – has high A-a gradient - ?pneumonia / aspiration</div><div class=\"answer-line\">Pressure areas from prolonged lie on floor</div><div class=\"answer-line\">Compartment syndromes from long lie on floor</div><div class=\"answer-line\">Other sources of sepsis – cellulitis / abdomen / meningitis</div><div class=\"answer-line\">PR for blood loss / melaena</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>ECG</strong> – looking for cause of fall eg STEMI, arrhythmia</td><td>CXR – define lung injury eg pneumonia</td></tr><tr><td>Urine M/C/S – exclude UT in sepsis / myoglobin in rhabdo</td><td>FBC – look for MCV to classify anaemia / help define cause</td></tr><tr><td>Chem 20 – look for AKI due to dehydration / rhabdo</td><td>CT head – exclude ICH in anti-coagulated person who has fallen</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 65 year old woman has presented with sudden onset visual loss in her left eye.\nYour junior doctor was concerned about a central retinal artery occlusion (CRAO).","parts":[{"id":"p1","label":"Part 1","prompt":"List 2 findings from your eye examination that would be consistent with a CRAO.\n(2 marks)"},{"id":"p2","label":"Part 2","prompt":"State 5 differential diagnoses, apart from CRAO. For each, provide a cardinal finding of\nyour examination. (5 marks) Your eye examination is consistent with a CRAO."},{"id":"p3","label":"Part 3","prompt":"State 5 components of your further non-ocular examination or investigation. Include the\nclinical relevance of each. (5 marks)\nPAH 2025.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Cherry red spot macula</div><div class=\"answer-line\">Ischaemic / pale retina</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Vitreous haemorrhage – red posterior chamber, unable to visualise retina</td><td>Retinal detachment – area of detached retina on fundoscopy</td></tr><tr><td>CRVO – “blood and thunder” retinal haemorrhages</td><td>Optic neuritis – RAPD, swollen optic disc</td></tr><tr><td>GCA – tender temporal artery, swollen optic disc</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">ECG – for AF as cardiac source of embolus</div><div class=\"answer-line\">CTA – looking for carotid disease as source of embolus</div><div class=\"answer-line\">Signs of endocarditis eg new regurgitant murmur – source of embolus</div><div class=\"answer-line\">Carotid bruit – carotid stenosis – embolus</div><div class=\"answer-line\">Echo – looking for cardiac thrombus eg LV in severe cardiomyopathy or atrial in AF</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 50 year old woman has presented with a painful left elbow.\nA clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the most likely diagnosis supported by 2 features from the photo. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 potential causes of this problem. For each, provide a supportive finding from your\nhistory. (4 marks) Potential cause Supportive finding from history"},{"id":"p3","label":"Part 3","prompt":"Provide 4 potential treatment options, including the clinical indication for each. (4 marks) Treatment option Clinical indication"}],"propPages":["asset:imgbc8e8f73991386d3bb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Olecranon bursitis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Swollen over olecranon</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Red</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Septic bursitis – fever, unwell, foreign body</td><td>Traumatic – Hx trauma, prolonged pressure</td></tr><tr><td>Gout – Hx gout</td><td>Inflammatory – eg Hx rheumatoid arthritis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Antibiotics eg fluclox 500mg QID po – for infective causes, septic</td><td>NSAIDS ibuprofen 400mg tds – for inflammatory causes</td></tr><tr><td>Operative drainage – septic, not improving with Abs</td><td>Corticosteroid injection – for known inflammatory conditions</td></tr><tr><td>Gout Rx – eg colchicine 500mg bd, NSAIDs, prenisone 50mg od</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 50 year old man has presented with central chest pain.","parts":[{"id":"p1","label":"Part 1","prompt":"Aside from ECG findings, list 6 other high-risk features from the National Heart Foundation Guideline for acute coronary syndromes you might find in your assessment. (6 marks) After comprehensive assessment, you have concluded the patient has cardiac sounding chest pain with no high-risk features and is appropriate for outpatient follow-up."},{"id":"p2","label":"Part 2","prompt":"State 5 components of your discharge instructions. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Ongoing / repetitive chest pain</div><div class=\"answer-line\">Elevated TnI</div><div class=\"answer-line\">Haemodynamic compromise – hypotension, heart failure</div><div class=\"answer-line\">VT</div><div class=\"answer-line\">Syncope</div><div class=\"answer-line\">Known LV dysfunction</div><div class=\"answer-line\">Prior MI/PCI/CABG last 6 months</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Aspirin 100mg od</div><div class=\"answer-line\">GTN spray – instruct how to use</div><div class=\"answer-line\">Advice when to return – recurrent pain more than 10 min</div><div class=\"answer-line\">LMO follow up – further provocative testing</div><div class=\"answer-line\">Risk factor modification – eg smoking/hypertension/high chol</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 75 year old man has been brought to hospital with a reduced level of consciousness.\nHe has a history of liver cirrhosis due to chronic alcohol abuse. You suspect that the patient has decompensated liver failure resulting in hepatic encephalopathy.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 conditions that might cause this problem. For each, provide a key finding from your assessment (history, examination or investigation). (6 marks) Condition Assessment finding Following assessment, a subdural haemorrhage has been identified as the cause of the patient’s reduced level of consciousness. 2.\nState 5 factors you would consider in your further management of this patient. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><strong>GI bleed</strong> – melaena on PR exam / haematemesis</td><td>SBP – generalised abdominal pin with ascites, SBP on ascitic fluid analysis (wbc &gt;250/uL)</td></tr><tr><td>EtOH excess – Hx increased use recently</td><td>Other sepsis eg UTI – urinary symptoms / fever</td></tr><tr><td>Non-compliance with lactulose / meds – Hx not taking medications</td><td>Constipation – hard stool on PR</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"An 8 year old girl has been brought to the ED with abdominal pain and vomiting.\nA venous blood gas is provided below.\n\npH\n7.10 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3-\nmmHg (22 - 28)\n\nBE\n-12 mmol/L (-3 - +3)\n\nNa\n125 mmol/L (135 - 145)\n\nK\n6.0 mmol/L (3.4 - 5.0)\n\nCl\nmmol/L (98 - 106)\n\nGlucose\nmmol/L (3.5 - 5.5) 1.\nState 4 abnormalities from the blood gas, supported by calculations where appropriate.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide the explanation for each. (8 marks) The patient has the following vital signs:\n\nGCS\nPulse 130 /min\n\nBP\n80/50 mmHg\n\nRR\n/min O2 sats 92% room air Temperature 38.5 degrees 2."},{"id":"p2","label":"Part 2","prompt":"List 4 other investigations you would perform, including justification. (4 marks)\n3."},{"id":"p3","label":"Part 3","prompt":"State 6 components of your management. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CO2 18 – expected 1.5 * 6 + 8 = 17 – appropriate resp compensation</td><td>Na 125 – corrected for glucose – (38-5)/3 = 11 – corrected 136 normal</td></tr><tr><td>K 6.0 – corrected for acidosis – 3*0.5 =1.5 – corrected 4.5 when pH is fixed</td><td>Raised glucose – DKA</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Ketones – confirm DKA and monitor for treatment success</div><div class=\"answer-line\">ECG – severity hyperkalaemia</div><div class=\"answer-line\">CXR – look for pneumonia as precipitant – pt has low sats</div><div class=\"answer-line\">Renal function – establish degree of AKI</div><div class=\"answer-line\">BC – identify pathogen to rationalise Abs in coming days</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>IV Abs</strong> – depend on results but likely pneumonia – ceftriaxone 50mg/kg, fluclox 50mg/kg</div><div class=\"answer-line\">K management – replace 40mmol/L in ongoing fluids once K below 5.0 mmol/L</div><div class=\"answer-line\">IV dextrose – add 5%D to N/S once BSL &lt;12</div><div class=\"answer-line\">Ongoing fluid – deficit (replace over 24/hr) plus maintenance after bolus</div><div class=\"answer-line\">Endocrine consult</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 53 year old woman has been admitted to the short stay unit over night for atraumatic lower back pain. 1. Complete the table regarding nerve root examination in sciatica. (6 marks) Nerve root Dermatome Myotome L4 L5 S1 2.\nList 4 features of your examination that would indicate an urgent MRI to be performed.\n(4 marks) Your diagnosis is sciatica due to L5 nerve root compression. There are no sinister examination findings.","parts":[{"id":"p3","label":"Part 3","prompt":"State 3 conditions that would need to be met for the patient to be discharged. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">L4 medial knee/calf ankle dorsiflexion</div><div class=\"answer-line\">L5 lateral calf great toe dorsiflexion</div><div class=\"answer-line\">S1 lateral foot ankle plantarflexion</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Saddle anaesthesia</div><div class=\"answer-line\">Loss anal tone</div><div class=\"answer-line\">Bilateral weakness / multiple myotomes</div><div class=\"answer-line\">Bilateral multiple dermatomal sensory loss</div><div class=\"answer-line\">Loss reflexes more than one</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Pain controlled</div><div class=\"answer-line\">Can mobilise</div><div class=\"answer-line\">Has follow up with LMO</div><div class=\"answer-line\">Knows red  flags for return – weakness, other signs cauda equina syndrome</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 34 year old man has presented with burns to his body following a house fire.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 techniques to assess the percentage of total body surface area (TBSA) involved in the burn injury. State an advantage of each method. (3 marks) Your initial assessment is consistent with 30% TBSA burns. There are no airway or facial burns. He has full thickness burns to his left arm."},{"id":"p2","label":"Part 2","prompt":"List 4 features of your assessment that would suggest the requirement for an escharotomy\nto the left arm. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"State your strategy for fluid administration. (2 marks)"},{"id":"p4","label":"Part 4","prompt":"State 4 other components of your management. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Lund and Browder chart – most accurate</div><div class=\"answer-line\">Rule of Nine’s – simplest method for large TBSA burns</div><div class=\"answer-line\">Patient’s palm 1% rule – useful for smaller TBSA estimation</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Pallor, cyanosed hand</div><div class=\"answer-line\">Absent cap refill in unburned areas</div><div class=\"answer-line\">Coolness</div><div class=\"answer-line\">Loss of palpable pulses</div><div class=\"answer-line\">Decrease oxygen sats on pulse oximetry</div><div class=\"answer-line\">Circulation compromise not relieved by elevation</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Parkland formula</div><div class=\"answer-line\">4*BSA*wt = volume fluid in first 24 hours – half in first 8 hours</div><div class=\"answer-line\">Hartmanns</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Analgesia – IV morphine 2.5 – 5mg aliquots until comfortable</div><div class=\"answer-line\">First aid – cool burn – col water / cool compresses</div><div class=\"answer-line\">ADT</div><div class=\"answer-line\">Burn unit transfer</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 3 year old child has been brought to the ED with an acute choking episode which began while playing with a balloon. The child is responsive. 1.\nState 2 initial treatment measures you might institute. Provide the indication for each.\n(2 marks) The child has become unresponsive despite your initial treatment. There is no palpable pulse. 2.","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 components of your immediate management. (3 marks)\n3. State 3 potential strategies for dealing with the airway obstruction. Include the situation"},{"id":"p2","label":"Part 2","prompt":"in which you would adopt each option. (3 marks) The child has been intubated and has spontaneous circulation. The foreign body was unable to be retrieved. 4."},{"id":"p3","label":"Part 3","prompt":"State 4 factors you will consider when ventilating the child. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">If effective cough – encourage coughing</div><div class=\"answer-line\">If not – 5 back blows</div><div class=\"answer-line\">If back blows not effective – 5 chest thrusts</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">2 rescue breaths</div><div class=\"answer-line\">CPR 15:2 2 rescuers</div><div class=\"answer-line\">Adrenaline 10mcg/kg</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Remove balloon with McGills forceps if visible above cords</div><div class=\"answer-line\">Pass ETT past balloon if not possible to retrieve</div><div class=\"answer-line\">Push FB in to right main bronchus if unable to retrieve and obstructing trachea</div><div class=\"answer-line\">4.</div><div class=\"answer-line\">Potential main bronchus obstruction – may need to reduce tidal volume to avoid barotrauma</div><div class=\"answer-line\">Child weight – will aim 6mL/kg TV</div><div class=\"answer-line\">Peak pressure – aim peak plateau pressure less than 30cmH20 (or peak less than 40) to avoid</div><div class=\"answer-line\">barotrauma</div><div class=\"answer-line\">RR – aim for normocapnoea – may need to increase RR if high CO2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 19 year old man has been brought to the ED after diving in to a pool while intoxicated.\nHe complained of neck pain. A slice from the CT scan of his neck is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the abnormalities shown. (4 marks) The patient has an absent bulbocavernosus reflex."},{"id":"p2","label":"Part 2","prompt":"Explain the significance of this finding. (2 marks)"},{"id":"p3","label":"Part 3","prompt":"List 5 other key features of your examination, including the significance of each. (5 marks) There are no other injuries."},{"id":"p4","label":"Part 4","prompt":"List 6 treatments you might employ in the ED. Provide the clinical indication for each.\n(6 marks)"}],"propPages":["asset:img60235ed6da214250ee"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Anterolisthesis 50% C6 on 7</div><div class=\"answer-line\">Soft tissue widening – haematoma</div><div class=\"answer-line\">Loss anterior and posterior spinal lines</div><div class=\"answer-line\">Widened interspinous space C6/7 – interspinous ligament disruption</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Pt has spinal shock</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Examination of motor and sensory weakness may be inaccurate (actual deficits may not be</div><div class=\"answer-line\">as severe as they currently are)</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Pulse/BP</strong> – looking for neurogenic shock (bradycardia/hypotension)</div><div class=\"answer-line\"><strong>Hypoventilation d</strong>ue to resp muscle paralysis – raised CO2 – may require intubation</div><div class=\"answer-line\">Hypoxia – aspiration common – may require ventilation</div><div class=\"answer-line\">Motor level – establish degree of current incapacity</div><div class=\"answer-line\">Sensory level – establish degree of current incapacity</div><div class=\"answer-line\">Anal tone – complete/incomplete injury (although current spinal shock affects this assessment)</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Intubation / ventilation – raised CO2 / hypoxia / vomiting and can’t protect airway</td><td>Adrenaline infusion – hypotension/bradycardia from neurogenic shock</td></tr><tr><td>IDC – all spinal injured patients with paralysis – prevent bladder injury</td><td>NGT – if vomiting to empty stomach – decrease risk aspiration</td></tr><tr><td>Forced air warmer – hypothermic patient due to vasoplegia</td><td>IV N/S 1L stat – neurogenic shock, in addition to inotropes</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 21 year old man has presented with left wrist pain following a push-bike accident.\nHis x-rays are provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the abnormalities shown. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 acute complications of this injury. For each, list the clinical features that would suggest its presence. (6 marks) Complication Clinical features"},{"id":"p3","label":"Part 3","prompt":"State 4 components of your management. (4 marks)"}],"propPages":["asset:imgab75eb724c1792d439","asset:imgf18bece32fc9b07a49"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Trans-scaphoid peri-lunate dislocation</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Fractured scaphoid</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Distal carpal row dorsally dislocated</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Median nerve injury – sensory deficit lateral palm, loss thumb abduction</td><td>Compartment syndrome – tense anterior forearm/wrist, pale, cool hand, loss cap refill</td></tr><tr><td>Ulnar nerve injury – loss sensation medial palm, loss finger abduction/adduction</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Analgesia - IV morphine 2.5mg prn until comfortable</div><div class=\"answer-line\"><strong>Reduction under sedation </strong></div><div class=\"answer-line\">Plaster immobilisation</div><div class=\"answer-line\">Admit hand surgery</div><div class=\"answer-line\">Elevate and observe for compartment syndrome</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
